13	func TestNormalizeField(t *testing.T) {
14		cases := []struct {
15			name  string
16			in    string
17			want  string
18			valid bool
19		}{
20			{"plain", "B-001", "B-001", true},
21			{"trims ends", "\t B-001 \n", "B-001", true},
22			{"keeps interior", "B 001", "B 001", true},
23			{"keeps case", "b1", "b1", true},
24			{"empty", "", "", false},
25			{"only whitespace", " \t\n", "", false},
26		}
27		for _, tc := range cases {
28			t.Run(tc.name, func(t *testing.T) {
29				got, err := NormalizeField(tc.in)
30				if tc.valid {
31					if err != nil {
32						t.Fatalf("unexpected error: %v", err)
33					}
34					if got != tc.want {
35						t.Fatalf("got %q, want %q", got, tc.want)
36					}
37				} else if err == nil {
38					t.Fatalf("expected error for %q, got %q", tc.in, got)
39				}
40			})
41		}
42	}
43	
44	func TestParseQuantity(t *testing.T) {
45		const max = "9223372036854775807"
46		valid := map[string]int64{
47			"1":                   1,
48			"0007":                7,
49			"120":                 120,
50			max:                   MaxQuantity,
51			"0000000000000000001": 1,
52		}
53		for in, want := range valid {
54			got, err := ParseQuantity(in)
55			if err != nil {
56				t.Fatalf("ParseQuantity(%q) unexpected error: %v", in, err)
57			}
58			if got != want {
59				t.Fatalf("ParseQuantity(%q) = %d, want %d", in, got, want)
60			}
61		}
62		invalid := []string{
63			"0", "0000", "-1", "+1", "1.0", "1e3", " 1", "1 ",
64			"abc", "１２", "9223372036854775808", "99999999999999999999999", "",
65		}
66		for _, in := range invalid {
67			if _, err := ParseQuantity(in); err == nil {
68				t.Fatalf("ParseQuantity(%q) expected error", in)
69			}
70		}
71	}
72	
73	func writeRegistry(t *testing.T, path, content string) {
74		t.Helper()
75		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
76			t.Fatal(err)
77		}
78		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
79			t.Fatal(err)
80		}
81	}
82	
83	func TestRegisterCreatesAndPersists(t *testing.T) {
84		path := filepath.Join(t.TempDir(), "nested", "registry.json")
85	
86		reg, existed, err := Load(path)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if existed {
91			t.Fatal("registry should not exist yet")
92		}
93		out, err := Register(reg, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
94		if err != nil {
95			t.Fatal(err)
96		}
97		if !out.Created || out.Batch.Quantity != 120 {
98			t.Fatalf("unexpected outcome: %+v", out)
99		}
100		if err := Save(path, reg); err != nil {
101			t.Fatal(err)
102		}
103	
104		// Restart: old batch must still be recognized.
105		reg2, existed, err := Load(path)
106		if err != nil || !existed {
107			t.Fatalf("reload: existed=%v err=%v", existed, err)
108		}
109		out, err = Register(reg2, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
110		if err != nil {
111			t.Fatal(err)
112		}
113		if out.Created {
114			t.Fatal("identical repeat should be a duplicate, not a create")
115		}
116	
117		// A second batch keeps the first one intact.
118		_, err = Register(reg2, Input{Batch: "B-2", Product: "P-8", Quantity: 1, Unit: "box"})
119		if err != nil {
120			t.Fatal(err)
121		}
122		if err := Save(path, reg2); err != nil {
123			t.Fatal(err)
124		}
125		data, err := os.ReadFile(path)
126		if err != nil {
127			t.Fatal(err)
128		}
129		var parsed Registry
130		if err := json.Unmarshal(data, &parsed); err != nil {
131			t.Fatal(err)
132		}
133		if len(parsed.Batches) != 2 || parsed.Version != FormatVersion {
134			t.Fatalf("unexpected persisted content: %s", data)
135		}
136	}
137	
138	func TestDuplicateDoesNotRewriteFile(t *testing.T) {
139		path := filepath.Join(t.TempDir(), "registry.json")
140		writeRegistry(t, path, `{"version":1,"batches":[{"batch":"B-1","product":"P-7","quantity":120,"unit":"kg"}]}`)
141		before, err := os.Stat(path)
142		if err != nil {
143			t.Fatal(err)
144		}
145	
146		reg, _, err := Load(path)
147		if err != nil {
